#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 internal static class OperationDialogTests {
  static void Open(Window w){SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));w.WindowStartupLocation=WindowStartupLocation.Manual;w.Left=-18000;w.Top=-18000;w.ShowActivated=false;w.ShowInTaskbar=false;w.Show();NavigationTests.Wait(Task.Delay(120));w.UpdateLayout();}
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();var windows=new List<Window>();string old=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);checks.Add(text);};try{L.ChangeLanguage("cs");FluentTheme.Ensure();AppearanceTheme.Apply("Light");WorkflowStore.TestRoot=Path.Combine(root,"workflow");string sample=Path.Combine(root,"Nabídka.txt");File.WriteAllText(sample,"demo");var entries=new List<Entry>{new Entry{FullPath=sample,Name="Nabídka.txt",Bytes=4}};
   foreach(string motif in new[]{"Classic","Clean"}){
    AppearanceTheme.SetMotif(motif);
    var copy=new CopySetupDialog(null,entries,root,new string[0],false,new ProgramSettings());windows.Add(copy);Open(copy);CheckPages(copy,motif+"-copy",root,check);var options=copy.CreateOptions(true);check(options.Queue&&!options.Move&&options.Rule==CopyRule.Ask&&options.Filter=="*.*",motif+": cleaned copy dialog preserves queue and default conflict policy");Shot(copy,motif+"-copy",root,check);
    var copyNav=FluentUiTests.Children<ListBox>(copy).Single();copyNav.SelectedIndex=3;
    FluentUiTests.Children<CheckBox>(copy).Single(x=>(string)x.Content==L.Text("copy.verifySha256Option")).IsChecked=true;
    copyNav.SelectedIndex=1;FluentUiTests.Children<ComboBox>(copy).Single(x=>x.IsEditable&&x.Text=="*.*").Text="*.txt";copyNav.SelectedIndex=0;
    check(copy.CreateOptions(false).Verify&&copy.CreateOptions(false).Filter=="*.txt",motif+": copy verification and file mask survive page switching");copy.Close();windows.Remove(copy);
    var deletion=new DeleteConfirmationDialog(null,entries,true,false,root);windows.Add(deletion);Open(deletion);check(deletion.Recycle.IsDefault&&!deletion.Permanent,motif+": delete still defaults to recycle");check(FluentUiTests.Children<GroupBox>(deletion).Count()==2,motif+": deletion separates selection and removal methods");check(FluentUiTests.Children<Button>(deletion).Any(x=>(string)x.Content==L.Text("delete.permanentTitle")&&x.IsVisible),motif+": permanent deletion is explicitly labeled");Shot(deletion,motif+"-delete",root,check);deletion.Close();windows.Remove(deletion);
    var pack=new ArchivePackDialog(null,1,Path.Combine(root,"Dokumenty.zip"));windows.Add(pack);Open(pack);check(FluentUiTests.Children<ComboBox>(pack).Any(x=>x.Items.Count==7&&x.Items.Cast<object>().Contains("7-ZIP"))&&FluentUiTests.Children<CheckBox>(pack).Any(x=>(string)x.Content==L.Text("archive.multiVolume")&&x.IsEnabled),motif+": archive formats and volume options remain available");CheckPages(pack,motif+"-pack",root,check);Shot(pack,motif+"-pack",root,check);var format=FluentUiTests.Children<ComboBox>(pack).Single(x=>x.Items.Cast<object>().Contains("7-ZIP"));format.SelectedItem="7-ZIP";check(FluentUiTests.Children<TextBox>(pack).Any(x=>x.Text.EndsWith(".7z")),motif+": archive format selection still changes the output extension");var packNav=FluentUiTests.Children<ListBox>(pack).Single();packNav.SelectedIndex=3;var password=FluentUiTests.Children<CheckBox>(pack).Single(x=>(string)x.Content==L.Text("archive.setPassword"));password.IsChecked=true;var secret=FluentUiTests.Children<PasswordBox>(pack).Single();secret.Password="demo";packNav.SelectedIndex=1;packNav.SelectedIndex=3;check(secret.Password=="demo"&&password.IsChecked==true,motif+": archive password survives page switching");
    format.SelectedItem="TAR";check(!password.IsEnabled&&!secret.IsEnabled&&secret.Password.Length==0&&!FluentUiTests.Children<CheckBox>(pack).Single(x=>(string)x.Content==L.Text("archive.multiVolume")).IsEnabled,motif+": unsupported format disables password and split options");pack.Close();windows.Remove(pack);
    var profile=new NetworkProfile{Name="KLADNO",Host="10.0.10.101",Port=65000,UserName="JR",Protocol=NetworkProtocol.FTP};
    var network=new NetworkCopyDialog(null,1,@"F:\","/Media1",null,profile);windows.Add(network);Open(network);var networkNav=FluentUiTests.Children<ListBox>(network).Single();
    check(networkNav.Items.Count==2&&networkNav.SelectedIndex==0,motif+": network setup has Basic and Transfer details sidebar pages");check(!FluentUiTests.Children<Expander>(network).Any(),motif+": network setup has no expanding sections");
    check(network.RulePicker.Items.Count==3&&network.RulePicker.IsVisible&&network.Start.IsVisible,motif+": collision choices and the single start action are visible");
    Shot(network,motif+"-network-setup",root,check);double networkHeight=network.ActualHeight;networkNav.SelectedIndex=1;network.UpdateLayout();check(Math.Abs(network.ActualHeight-networkHeight)<1,motif+": network setup sidebar preserves height");NextStageTests.Draw(network,Path.Combine(root,motif+"-network-setup-details.png"));network.Close();windows.Remove(network);
    foreach(var pair in new[]{Tuple.Create("transfer.copyAndSkip",NetworkCopyRule.Skip),Tuple.Create("transfer.copyAndOverwrite",NetworkCopyRule.Overwrite),Tuple.Create("transfer.copyAndResume",NetworkCopyRule.Resume)})check(NetworkAnswer(profile,pair.Item1,pair.Item2),motif+": network setup preserves decision "+pair.Item2);
    check(NetworkAnswer(profile,"action.cancel",null),motif+": cancelling network setup does not accept transfer");
    var moveNetwork=new NetworkCopyDialog(null,2,"/Media1",@"F:\",profile,null,true);windows.Add(moveNetwork);Open(moveNetwork);check(FluentUiTests.Children<TextBlock>(moveNetwork).Any(x=>x.IsVisible&&x.Text.Contains(L.Text("transfer.moveSourceDeletionHelp"))),motif+": network move shows source deletion notice immediately");moveNetwork.Close();windows.Remove(moveNetwork);
    var extract=new ArchiveExtractDialog(null,new[]{Path.Combine(root,"Dokumenty.zip")},root);windows.Add(extract);Open(extract);check(FluentUiTests.Children<ComboBox>(extract).Single().SelectedIndex==0,motif+": extraction still skips existing files by default");Shot(extract,motif+"-extract",root,check);extract.Close();windows.Remove(extract);
   }
   File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{foreach(var w in windows.ToArray())w.Close();AppearanceTheme.SetMotif(old);}}
  static bool NetworkAnswer(NetworkProfile target,string key,NetworkCopyRule? expected){var dialog=new NetworkCopyDialog(null,1,@"F:\","/Media1",null,target);dialog.WindowStartupLocation=WindowStartupLocation.Manual;dialog.Left=-18000;dialog.Top=-18000;dialog.ShowInTaskbar=false;dialog.ShowActivated=false;dialog.Loaded+=delegate{dialog.Dispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(delegate{if(expected.HasValue){dialog.SelectRule(expected.Value);dialog.Start.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}else FluentUiTests.Children<Button>(dialog).Single(x=>(string)x.Content==L.Text(key)).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}));};var result=dialog.ShowDialog();return expected.HasValue?result==true&&dialog.Rule==expected.Value:result!=true;}
  static void CheckPages(Window w,string name,string root,Action<bool,string> check){
   var nav=FluentUiTests.Children<ListBox>(w).Single();double height=w.ActualHeight;check(nav.Items.Count==5&&nav.SelectedIndex==0,name+": five sidebar categories start on the basic page");
   for(int i=0;i<nav.Items.Count;i++){nav.SelectedIndex=i;w.UpdateLayout();NavigationTests.Wait(Task.Delay(40));w.UpdateLayout();check(Math.Abs(w.ActualHeight-height)<1,name+": category "+i+" preserves window height");NextStageTests.Draw(w,Path.Combine(root,name+"-page-"+i+".png"));}
   nav.SelectedIndex=0;w.UpdateLayout();
  }
  static void Shot(Window w,string name,string root,Action<bool,string> check){check(FluentUiTests.Children<TextBlock>(w).Any(x=>x.FontSize==20&&x.IsVisible),name+": visible clean operation header");NextStageTests.Draw(w,Path.Combine(root,name+".png"));}
 }
}
#endif
